using System.Collections.Generic;
using System.Globalization;
using UnityEngine;

namespace WoodsGame
{
    /// <summary>Catalog of the loadable maps (one scene each): the overworld, the towns and Monte Ceniza, plus the gates
    /// that join them. Generated by Tools/GameGen/maps.py (Assets/Game/Levels/Maps.txt), copied by the builder to
    /// Resources/MapsCatalog.txt together with the overworld's region grid (for the world map shown from inside a town).</summary>
    public static class MapDB
    {
        public const string World = "World";
        public const string StartMap = "World";                 // one single map (2026-11-21): everything lives in World

        public class MapDef
        {
            public string id, kind, title, subtitle;
            public int w, h;
            public char region;
            /// <summary>Footprint inside the overworld (tile x0,row0,x1,row1) - towns and the volcano. Empty for World.</summary>
            public RectInt area;
            public bool hasArea, blocksArea;
            public bool IsWorld => kind == "world";
            /// <summary>Centre of the footprint in overworld units (y up).</summary>
            public Vector2 WorldAnchor => hasArea ? new Vector2((area.xMin + area.xMax + 1) / 2f, WorldH - (area.yMin + area.yMax + 1) / 2f) : Vector2.zero;
        }

        public class GateDef
        {
            public string map, id, toMap, toGate;
            public Vector2 center, size, arrival, facing;
        }

        /// <summary>A place merged into the one map: a town, Monte Ceniza or a cave of the underground (cells, top row first).</summary>
        public class PlaceDef
        {
            public string id, kind, title, subtitle;      // kind: town | zone | cave
            public RectInt cells;                         // x0,row0 .. x1,row1 inclusive (xMax/yMax = x1/row1)
            public char region;
            public bool Contains(int x, int row) => x >= cells.xMin && x <= cells.xMax && row >= cells.yMin && row <= cells.yMax;
            /// <summary>World-space rect (units, y up).</summary>
            public Rect Bounds => new Rect(cells.xMin, WorldH - 1 - cells.yMax, cells.xMax - cells.xMin + 1, cells.yMax - cells.yMin + 1);
            public Vector2 Center => Bounds.center;
        }

        static List<PlaceDef> _places;
        static Dictionary<string, Vector2> _merged;
        /// <summary>The overworld part of the map (the underground lies to its right).</summary>
        public static int SurfaceW = 240, SurfaceH = 160;
        public static IReadOnlyList<PlaceDef> Places { get { Load(); return _places; } }
        /// <summary>Old saves made in a separate town/zone map: offset that turns its positions into the merged map's.</summary>
        public static bool MergedOffset(string oldMap, out Vector2 offset) { Load(); return _merged.TryGetValue(oldMap ?? "", out offset); }

        public static PlaceDef PlaceAt(Vector2 worldPos, string kind = null)
        {
            Load();
            int x = Mathf.FloorToInt(worldPos.x), row = WorldH - 1 - Mathf.FloorToInt(worldPos.y);
            foreach (var p in _places) if ((kind == null || p.kind == kind) && p.Contains(x, row)) return p;
            return null;
        }
        public static PlaceDef Place(string id) { Load(); return _places.Find(p => p.id == id); }

        static List<MapDef> _maps;
        static List<GateDef> _gates;
        static string[] _worldRegions;
        static Dictionary<char, string> _regionNames = new Dictionary<char, string>();
        public static int WorldW = 240, WorldH = 160;

        public static IReadOnlyList<MapDef> Maps { get { Load(); return _maps; } }
        public static IReadOnlyList<GateDef> Gates { get { Load(); return _gates; } }
        /// <summary>Overworld region ids, one string per tile row (top row first).</summary>
        public static string[] WorldRegions { get { Load(); return _worldRegions; } }

        public static string RegionName(char id) { Load(); return _regionNames.TryGetValue(id, out var n) ? n : ""; }

        public static MapDef Get(string id)
        {
            foreach (var m in Maps) if (m.id == id) return m;
            return null;
        }

        public static bool Exists(string id) => !string.IsNullOrEmpty(id) && Get(id) != null;

        public static GateDef Gate(string map, string id)
        {
            foreach (var g in Gates) if (g.map == map && g.id == id) return g;
            return null;
        }

        /// <summary>Persistent ids of chests, campfires... Overworld ids keep the old "prefix_x_y" form (old saves still work);
        /// the other maps add their name so two maps never share an id.</summary>
        public static string Key(string prefix, Vector2 pos, string map)
        {
            int x = Mathf.RoundToInt(pos.x), y = Mathf.RoundToInt(pos.y);
            return string.IsNullOrEmpty(map) || map == World ? $"{prefix}_{x}_{y}" : $"{prefix}_{map}_{x}_{y}";
        }

        /// <summary>The town or zone whose overworld footprint contains this overworld point (null when none).</summary>
        public static MapDef AreaAt(Vector2 worldPos)
        {
            int x = Mathf.FloorToInt(worldPos.x), row = WorldH - 1 - Mathf.FloorToInt(worldPos.y);
            foreach (var m in Maps)
                if (m.hasArea && x >= m.area.xMin && x <= m.area.xMax && row >= m.area.yMin && row <= m.area.yMax) return m;
            return null;
        }

        static float F(string s) => float.Parse(s, CultureInfo.InvariantCulture);

        static void Load()
        {
            if (_maps != null) return;
            _maps = new List<MapDef>(); _gates = new List<GateDef>(); _places = new List<PlaceDef>(); _merged = new Dictionary<string, Vector2>();
            var ta = Resources.Load<TextAsset>("MapsCatalog");
            if (ta == null) { Debug.LogWarning("[MapDB] Resources/MapsCatalog missing (run Tools > Game > Build Game)"); _worldRegions = new string[0]; return; }
            Parse(ta.text.Split('\n'));
        }

        /// <summary>Also used by the editor builder (same file format).</summary>
        public static void Parse(string[] lines)
        {
            _maps = new List<MapDef>(); _gates = new List<GateDef>(); _places = new List<PlaceDef>(); _merged = new Dictionary<string, Vector2>();
            var regions = new List<string>();
            bool inRegions = false;
            foreach (var raw in lines)
            {
                var l = raw.TrimEnd('\r');
                if (inRegions) { if (l.Length > 0) regions.Add(l); continue; }
                if (l.StartsWith("#") || l.Length == 0) continue;
                if (l == "WORLDREGIONS") { inRegions = true; continue; }
                var p = l.Split(' ');
                switch (p[0])
                {
                    case "MAP":
                    {
                        var t = string.Join(" ", p, 6, p.Length - 6).Split('|');
                        _maps.Add(new MapDef { id = p[1], kind = p[2], w = int.Parse(p[3]), h = int.Parse(p[4]), region = p[5][0],
                                               title = t[0], subtitle = t.Length > 1 ? t[1] : "" });
                        if (p[2] == "world") { WorldW = SurfaceW = int.Parse(p[3]); WorldH = SurfaceH = int.Parse(p[4]); }
                        break;
                    }
                    case "AREA":
                    {
                        var m = _maps.Find(x => x.id == p[1]);
                        if (m == null) break;
                        int x0 = int.Parse(p[2]), r0 = int.Parse(p[3]), x1 = int.Parse(p[4]), r1 = int.Parse(p[5]);
                        m.area = new RectInt(x0, r0, x1 - x0, r1 - r0); m.hasArea = true; m.blocksArea = p[6] == "1";
                        break;
                    }
                    case "SURFACE": SurfaceW = int.Parse(p[1]); SurfaceH = int.Parse(p[2]); break;
                    case "TOWN": case "ZONE": case "CAVE":
                    {
                        int x0 = int.Parse(p[2]), r0 = int.Parse(p[3]), x1 = int.Parse(p[4]), r1 = int.Parse(p[5]);
                        int ti = 6; char reg = '\0';
                        if (p[0] == "CAVE") { reg = p[6][0]; ti = 7; }
                        var t = string.Join(" ", p, ti, p.Length - ti).Split('|');
                        _places.Add(new PlaceDef { id = p[1], kind = p[0] == "TOWN" ? "town" : p[0] == "ZONE" ? "zone" : "cave",
                            cells = new RectInt(x0, r0, x1 - x0, r1 - r0), region = reg, title = t[0], subtitle = t.Length > 1 ? t[1] : "" });
                        break;
                    }
                    case "MERGED": _merged[p[1]] = new Vector2(F(p[2]), F(p[3])); break;
                    case "REGION":
                        _regionNames[p[1][0]] = string.Join(" ", p, 2, p.Length - 2);
                        break;
                    case "GATE":
                        _gates.Add(new GateDef
                        {
                            map = p[1], id = p[2], center = new Vector2(F(p[3]), F(p[4])), size = new Vector2(F(p[5]), F(p[6])),
                            arrival = new Vector2(F(p[7]), F(p[8])), facing = new Vector2(F(p[9]), F(p[10])), toMap = p[11], toGate = p[12],
                        });
                        break;
                }
            }
            _worldRegions = regions.ToArray();
        }
    }
}
